    97	      const result = validateMessage({type: 'list_conversations', ...frame});
    98	      return result.valid
    99	        ? 'valid'
   100	        : /limit/.test(result.error)
   101	          ? 'limit'
   102	          : /before/.test(result.error)
   103	            ? 'before'
   104	            : result.error;
   105	    };
