   120	      bounds: 'valid/valid',
   121	      zero: 'limit',
   122	      tooMany: 'limit',
   123	      fractional: 'limit',
   124	      text: 'limit',
   125	      notADate: 'before',
   126	      badCursor: 'before',
   127	      halfCursor: 'before',
   128	      cursor: 'valid',
