   135	    const before = {updatedAt: at(10), sessionId: 'zzzz'};
   136	
   137	    // Rejoins alpha, so the store holds exactly u1's three conversations and the connection adds none.
   138	    const answer = await askOn(`${url}?sessionId=alpha`, {type: 'list_conversations', userId: 'u2', limit: 10, before});
