   140	    const rows = lists[0]?.conversations ?? [];
   141	    const head = rows[0]?.sessionId ?? 'none';
   142	
   143	    expect({
   144	      // The replay of the rejoined conversation is resume's, not the list's answer.
   145	      types: answer.filter(frame => frame.type !== 'entry_upsert').map(frame => frame.type),
   146	      order: rows.map(row => row.sessionId),
   147	      iso: rows.every(
   148	        row => typeof row.createdAt === 'string' && ISO.test(row.createdAt) && ISO.test(String(row.updatedAt))
   149	      ),
   150	      listedFor: store.listCalls,
