   152	      types: ['conversation_list'],
   153	      order: ['beta', 'gamma', 'alpha'],
   154	      iso: true,
   155	      listedFor: [['u1', {limit: 10, before}]],
   156	    });
   157	
   158	    // The id a row carries opens that conversation through the existing resume path, replay included.
   159	    const client = connectClient(`${url}?sessionId=${head}`);
   160	    const connected = await new Promise<Frame[]>(resolve => {
   161	      const frames: Frame[] = [];
   162	      client.on('message', raw => {
   163	        const frame = JSON.parse(String(raw)) as Frame;
   164	        frames.push(frame);
   165	        if (frame.type === 'connected') client.send(JSON.stringify({type: 'ping', timestamp: 3}));
   166	        if (frame.type === 'pong') resolve(frames);
   167	      });
   168	    });
   169	    expect({
   170	      sessionId: connected[0]?.sessionId,
   171	      resumed: connected[0]?.resumed,
   172	      replayed: connected.filter(frame => frame.type === 'entry_upsert').length,
   173	    }).toEqual({sessionId: 'beta', resumed: true, replayed: 1});
   174	  });
   175	
   176	  it('answers UNSUPPORTED and no list when history is off, and when the store implements no listFor', async () => {
   177	    const off = await startEngineWith({sessionStore: seeded(new InMemorySessionStore())});
   178	    const unlistable = await startEngineWith({
   179	      sessionStore: withoutListFor(seeded(new InMemorySessionStore())),
   180	      ...HISTORY_ON,
   181	    });
   182	
   183	    const shape = (frames: Frame[]) => frames.map(frame => `${frame.type}:${frame.code ?? ''}`);
   184	
   185	    expect({
   186	      historyOff: shape(await askOn(off.url, {type: 'list_conversations'})),
   187	      noListFor: shape(await askOn(unlistable.url, {type: 'list_conversations'})),
   188	    }).toEqual({historyOff: ['error:UNSUPPORTED'], noListFor: ['error:UNSUPPORTED']});
   189	  });
   190	
   191	  it('answers a listFor that rejects with SERVER_ERROR carrying no store detail, logged by session, the socket left open', async () => {
   192	    const detail = 'connection to mongodb://secret-host refused';
   193	    const failing: SessionStore = {
   194	      ...withoutListFor(seeded(new InMemorySessionStore())),
   195	      listFor: async () => {
   196	        throw new Error(detail);
   197	      },
   198	    };
   199	    const {url} = await startEngineWith({sessionStore: failing, ...HISTORY_ON});
   200	    const client = connectClient(url);
   201	    let sessionId = '';
   202	    client.on('message', raw => {
   203	      const frame = JSON.parse(String(raw)) as Frame;
   204	      if (frame.type === 'connected') sessionId = frame.sessionId ?? '';
   205	    });
   206	
   207	    const answer = await ask(client, {type: 'list_conversations'});
   208	    const failure = logged.find(line => line.level === 'error');
