   210	    expect({
   211	      frames: answer.map(frame => ({
   212	        type: frame.type,
   213	        code: frame.code,
   214	        leaks: String(frame.message).includes('secret'),
   215	      })),
   216	      open: client.readyState === client.OPEN,
   217	      loggedSession: failure?.sessionId === sessionId && sessionId !== '',
   218	    }).toEqual({
   219	      frames: [{type: 'error', code: 'SERVER_ERROR', leaks: false}],
   220	      open: true,
   221	      loggedSession: true,
   222	    });
   223	  });
