   225	  it("answers list_conversations while a user_message is still streaming, before that turn's stream_end", async () => {
   226	    const hold = deferred();
   227	    const streaming: ChatOrchestrator = {
   228	      processMessage: async () => 'hi',
   229	      async *processMessageStream(): AsyncGenerator<MessageChunk> {
   230	        yield {type: 'text', text: 'hi'};
   231	        await hold.until;
   232	        yield {type: 'stop', stopReason: 'end_turn'};
   233	      },
   234	    };
   235	    const {url} = await startEngineWith({
   236	      sessionStore: seeded(new InMemorySessionStore()),
   237	      orchestrator: streaming,
   238	      ...HISTORY_ON,
   239	    });
   240	    const client = connectClient(url);
   241	
   242	    const seen = await new Promise<string[]>(resolve => {
   243	      const types: string[] = [];
   244	      // Released after a while regardless, so a list that waits on the lock shows up as an order, not a hang.
   245	      const fallback = setTimeout(() => hold.release(), 1000);
   246	      client.on('message', raw => {
   247	        const {type} = JSON.parse(String(raw)) as Frame;
   248	        types.push(type);
   249	        if (type === 'connected') client.send(JSON.stringify({type: 'user_message', content: 'hello'}));
   250	        if (type === 'entry_delta' && !types.includes('list_sent')) {
   251	          types.push('list_sent');
   252	          client.send(JSON.stringify({type: 'list_conversations'}));
   253	        }
   254	        if (type === 'conversation_list') hold.release();
   255	        if (type === 'stream_end') {
   256	          clearTimeout(fallback);
   257	          resolve(types);
   258	        }
   259	      });
   260	    });
   261	
   262	    const listAt = seen.indexOf('conversation_list');
   263	    expect({answered: listAt >= 0, beforeStreamEnd: listAt >= 0 && listAt < seen.indexOf('stream_end')}).toEqual({
   264	      answered: true,
   265	      beforeStreamEnd: true,
   266	    });
   267	  });
   268	});
